/// Concat of dictionary parts that do not share one dictionary (index type T): one merged
/// dictionary (the first dictionary as is, then each new distinct value of the next ones in
/// first-seen order; null entries share one slot), one old -> new index table per distinct
/// dictionary (values hashed once per dictionary, not per row), then the indices are gathered
/// through it. The merged dictionary must fit T and every non-null index must lie in its part's
/// dictionary (InvalidInput otherwise).
fn concatDictionaries(comptime T: type, allocator: std.mem.Allocator, dt: DataType, parts: anytype) Error!ArrayRef {
    const value_type = storageDataType(dt).dictionary.value_type.*;
    const kind = (try flatKind(storageDataType(value_type))) orelse return error.UnsupportedType;
    if (kind == .null_type or kind == .boolean or storageDataType(value_type) == .dictionary) return error.UnsupportedType;

    // Pass 1: types, rows, and each distinct dictionary (by node) with its remap table base.
    var bases: std.AutoHashMapUnmanaged(usize, usize) = .empty;
    defer bases.deinit(allocator);
    var dicts: std.ArrayList(ArrayRef) = .empty;
    defer dicts.deinit(allocator);
    var remap_len: usize = 0;
    var total_len: usize = 0;
    var maybe_nulls = false;
    var view: ArrayData = undefined;
    for (parts) |*part| {
        const d = partData(part, &view);
        try checkPartType(d, dt);
        const dict = d.dictionary orelse return error.InvalidInput;
        const gop = try bases.getOrPut(allocator, @intFromPtr(dict.node));
        if (!gop.found_existing) {
            gop.value_ptr.* = remap_len;
            remap_len = std.math.add(usize, remap_len, dict.data().length) catch return error.InvalidInput;
            try dicts.append(allocator, dict);
        }
        total_len = std.math.add(usize, total_len, d.length) catch return error.InvalidInput;
        maybe_nulls = maybe_nulls or ((d.null_count orelse 1) != 0 and d.buffers.len > 0 and !d.buffers[0].isEmpty());
    }

    // Merged dictionary = windows of the input dictionaries, concatenated at the end.
    const Merged = struct {
        windows: std.ArrayList(Part) = .empty,
        len: usize = 0,

        fn add(m: *@This(), a: std.mem.Allocator, ref: ArrayRef, row: usize) Error!T {
            if (m.len > std.math.maxInt(T)) return error.InvalidInput; // does not fit the index type
            const items = m.windows.items;
            if (items.len > 0 and items[items.len - 1].ref.node == ref.node and items[items.len - 1].start + items[items.len - 1].len == row) {
                items[items.len - 1].len += 1;
            } else try m.windows.append(a, .{ .ref = ref, .start = row, .len = 1 });
            m.len += 1;
            return @intCast(m.len - 1);
        }
    };
