test "array data validateFull checks UTF-8 of non-null string values like a per-value check" {
    const allocator = std.testing.allocator;
    const string_array = @import("string_array.zig");
    const view_array = @import("view_array.zig");
    // Pieces: ASCII runs (crossing 32-byte blocks), 2/3/4-byte characters, a lone lead byte, a lone
    // continuation byte, an overlong encoding and a surrogate.
    const pieces = [_][]const u8{ "a", "REDACTED", "\u{e9}", "\u{20ac}", "\u{1f600}", "\xc3", "\xa9", "\xc0\x80", "\xed\xa0\x80" };
    var prng = std.Random.DefaultPrng.init(7);
    const rng = prng.random();
    var values: [8]std.ArrayList(u8) = @splat(.empty);
    defer for (&values) |*v| v.deinit(allocator);
    for (0..1500) |_| {
        const n = rng.uintAtMost(usize, values.len);
        var valid_bits: [1]u8 = .{rng.int(u8)};
        for (values[0..n]) |*v| {
            v.clearRetainingCapacity();
            for (0..rng.uintAtMost(usize, 4)) |_| try v.appendSlice(allocator, pieces[rng.uintLessThan(usize, if (rng.uintLessThan(u8, 4) == 0) pieces.len else 5)]);
        }
        const off = rng.uintAtMost(usize, n);
        const len = rng.uintAtMost(usize, n - off);
        var expect_ok = true;
        for (off..off + len) |r| {
            if (bitmap.bitIsSet(&valid_bits, r) and !std.unicode.utf8ValidateSlice(values[r].items)) expect_ok = false;
        }

        var sb = try string_array.StringBuilder.init(allocator, n, 0);
        defer sb.deinit();
        var lb = try string_array.LargeStringBuilder.init(allocator, n, 0);
        defer lb.deinit();
        var vb = try view_array.StringViewBuilder.init(allocator, n, 0);
        defer vb.deinit();
        for (values[0..n]) |v| {
            try sb.append(v.items);
            try lb.append(v.items);
            try vb.append(v.items);
        }
        var arrays = [_]ArrayRef{ try sb.finish(), try lb.finish(), try vb.finish() };
        defer for (&arrays) |*a| a.release();
        for (arrays) |a| {
            var bufs: [8]SharedBuffer = undefined;
            const src = a.data().buffers;
            @memcpy(bufs[0..src.len], src);
            bufs[0] = SharedBuffer.fromSlice(&valid_bits); // invalid bytes behind null rows are not checked
            var d = a.data().*;
            d.buffers = bufs[0..src.len];
            d.offset = off;
            d.length = len;
            d.null_count = null;
            if (expect_ok) try d.validateFull() else try std.testing.expectError(error.InvalidUtf8, d.validateFull());
        }
    }
}
EOF
zig build test -j2 2>&1 | grep -v "^\s*$" | head -30; echo EXIT ${PIPESTATUS[0]}

